const text = $json.chatInput || "";

const match = text.match(/https?:\/\/[^\s\]]+/i);

const url = match ? match[0].replace(/\\+/g, "") : "";

return {
  chatInput: text,
  chatId: $json.chatId,
  url
};

const stats = $json.data?.attributes?.stats || {};

const malicious = Number(stats.malicious || 0);
const suspicious = Number(stats.suspicious || 0);
const harmless = Number(stats.harmless || 0);
const undetected = Number(stats.undetected || 0);

let score = 0;

score += malicious * 10;
score += suspicious * 5;

score = Math.min(100, score);

let risk;

if (score <= 19) {
  risk = "AMAN";
} else if (score <= 39) {
  risk = "WASPADA";
} else if (score <= 59) {
  risk = "MENCURIGAKAN";
} else if (score <= 79) {
  risk = "BERISIKO TINGGI";
} else {
  risk = "SANGAT BERISIKO";
}

return {
  json: {
    score,
    risk,
    malicious,
    suspicious,
    harmless,
    undetected
  }
};
